// === Tab: mySketch ===
//Fork basic sjadder structure from https://openprocessing.org/sketch/923286
//p5.js shader basic structure ref from https://www.openprocessing.org/sketch/920144
//Learn tutorial from https://www.youtube.com/watch?v=EO2ax570wKo&list=PL4neAtv21WOmIrTrkNO3xCyrxg4LKkrF7&index=24

let theShader;
let sourceGraphics,shaderGraphics;
var sizeMin;
var para = [];
var para01 = 0;
var para02;

function preload(){
	theShader = createShader(vert, frag)
}

function setup() {
	sizeMin = min(innerHeight, innerWidth)
	createCanvas(sizeMin,sizeMin);
	sourceGraphics= createGraphics(width,height)
	shaderGraphics = createGraphics(width,height,WEBGL)
	sourceGraphics.background(0) 
}

function draw() {
	sourceGraphics.background(0, 255)
	sourceGraphics.noStroke()
	sourceGraphics.fill(255)
	sourceGraphics.ellipse((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))),500,500)

	shaderGraphics.shader(theShader)
	theShader.setUniform('u_resolution',[width/sizeMin,height/sizeMin])
	theShader.setUniform('u_time',millis()*0.001)
	theShader.setUniform('u_tex',sourceGraphics)

	createAnimShader(0, 50, 300, 0, 7.0);
	createAnimShader(0, 300, 700, 7.0, 20.0);
	createAnimShader(0, 700, 1500, 20.0, 2.0);
	createAnimShader(0, 1500, 2500, 2.0, 100.0);
	createAnimShader(0, 2500, 3500, 100.0, 0.0);

	// para[1] = 10.0;

	theShader.setUniform('u_para',para01)

	shaderGraphics.rect(-width/2,-height/2,width,height)
	image(sourceGraphics,0,0)
	image(shaderGraphics,0,0)
	}

function createAnimShader(name, start, end, from, to){
	if(frameCount >= start && frameCount <= end){
		para01 = map(frameCount, start, end, from, to); 
	}
}

// === Tab: frag ===
//By me
// noprotect

const frag = `
	#ifdef GL_ES
	precision mediump float;
	#endif

	uniform vec2 u_resolution;
	uniform float u_time;
	uniform float u_para;
	uniform sampler2D u_tex;
	varying vec2 var_vertTexCoord;

	float random2d(vec2 coord){
  	return fract(sin(dot(coord.xy, vec2(100000.9898, 0.233))) * 43758.5453);
	}

	void main(){
		vec2 coord = var_vertTexCoord.xy / u_resolution.xy;		
		vec2 center = 0.5 - vec2(coord);

		center.x += sin(center.y * u_para * 0.5  + u_time * 0.5) * u_para * 0.01;

		vec3 color = vec3(0.0);  
		color += 0.01 / vec3(length(sin(u_time + center.x * 2.0 + cos(u_time * 0.3 + center.y * 4.0+ sin(u_time * 1.3 + center.x * u_para ))) * 0.1)) ; 
		color += 0.0005 / vec3(length(cos(u_time + center.x * 2.0 + sin(u_time * 0.3 * 0.1 + center.y * 4.0+ sin(u_time * 1.3 + center.x * 5.0 ))) * 0.1)) * u_para; 

		gl_FragColor = vec4(color.x, color.y, color.z, 1.0);
	}
`





// === Tab: vert ===
//ref 3d shader from https://www.openprocessing.org/sketch/881537

const vert = `
	precision highp float;

    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;
		varying vec4 var_centerGlPosition;//原点

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;
		uniform float u_time;


    void main() {
      vec3 pos = aPosition;
			vec4 posOut = uProjectionMatrix * uModelViewMatrix * vec4(pos, 1.0);
      gl_Position = posOut;

      // set out value
      var_vertPos      = pos;
      var_vertNormal   =  aNormal;
      var_vertTexCoord = aTexCoord;
			var_centerGlPosition = uProjectionMatrix * uModelViewMatrix * vec4(0., 0., 0.,1.0);
    }
`;

